import { ICloudBaseConfig } from '../types';
/**
 * 站点默认地域：国际站 `ap-singapore`（国际站环境通常在新加坡），其余 `ap-shanghai`。
 *
 * 站点来源（与 CLI 的判定口径一致：配置文件优先，环境变量兜底）：
 *   1. CLI 的站点配置 `config.json` 里的 `isIntl === true`（见 getCliConfigPaths）
 *   2. 环境变量 `TCB_IS_INTL === 'true'`（显式声明；CLI 在 `tcb login --intl` 时也会写入，
 *      作为配置文件不可读时的兜底）
 * 两者都没有时按国内站处理，保持既有行为。
 *
 * 仅在「命令行与配置文件都没有指定地域」时才会用到（见 getRegion）。
 */
export declare const getDefaultRegion: () => string;
/**
 * 获取 cloudbase 配置
 *
 * 配置文件路径优先级：显式入参 > setConfigSource 指定的 configPath > 命令行 `--config-path`。
 * 相对路径以 configSource.cwd 为基准（未设置时等价于 process.cwd）；
 * cwd 同时传给 ConfigParser，让 `.env` 的加载目录与之保持一致。
 */
export declare const getCloudBaseConfig: (configPath?: string) => Promise<ICloudBaseConfig>;
/**
 * 从命令行参数和配置文件中读取 region
 *
 * 优先级：`-r/--region` > cloudbaserc.json 的 region > 站点默认地域
 * （国际站 ap-singapore / 其余 ap-shanghai，见 getDefaultRegion）。
 */
export declare const getRegion: (noDefault?: boolean) => Promise<string>;
